#include "../crc64-cuda/CRC64.cu"
#include <vector>
#include <fstream>
#include <chrono>
#include <string>
#include <cstdio>
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
const uint64_t sentinel=UINT64_C(0x5a5a5a5a5a5a5a5a);
template<class T>std::vector<T>load(const char*name,size_t n){std::vector<T>x(n);std::ifstream f(std::string("/home/imo/HeCBench_julia/src/crc64-julia/")+name,std::ios::binary);f.read((char*)x.data(),n*sizeof(T));if(!f)exit(2);return x;}
int main(){std::vector<unsigned char>inputs[2]={load<unsigned char>("study_input1_u8.bin",65555),load<unsigned char>("study_input2_u8.bin",65677)};auto oracle=load<uint64_t>("oracle_u64.bin",281);for(auto &input:inputs)crc64_parallel(input.data(),input.size());CHECK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){std::vector<uint64_t>prefix,results,guards;double times[2];for(int ci=0;ci<2;ci++){auto &data=inputs[ci];size_t n=data.size();uint64_t actual[10];CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int j=0;j<10;j++)actual[j]=crc64_parallel(data.data(),n);CHECK(cudaDeviceSynchronize());times[ci]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;
unsigned char*d;uint64_t *t,*it,*cb;size_t*sb;CHECK(cudaMalloc(&d,n));CHECK(cudaMalloc(&t,8192));CHECK(cudaMalloc(&it,8192));CHECK(cudaMalloc(&cb,128*8));CHECK(cudaMalloc(&sb,128*8));std::vector<uint64_t>cr(128,sentinel);std::vector<size_t>sr(128,sentinel);CHECK(cudaMemcpy(d,data.data(),n,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(t,crc64_table,8192,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(it,crc64_interleaved_table,8192,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(cb,cr.data(),1024,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(sb,sr.data(),1024,cudaMemcpyHostToDevice));crc64_kernel<<<1,64>>>(sb+32,cb+32,d,t,it,n,64);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());CHECK(cudaMemcpy(cr.data(),cb,1024,cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(sr.data(),sb,1024,cudaMemcpyDeviceToHost));std::vector<unsigned char>rd(n);CHECK(cudaMemcpy(rd.data(),d,n,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),rd.begin(),rd.end());if(ci==1){std::vector<uint64_t>rt(1024),ri(1024);CHECK(cudaMemcpy(rt.data(),t,8192,cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(ri.data(),it,8192,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),rt.begin(),rt.end());prefix.insert(prefix.end(),ri.begin(),ri.end());}results.insert(results.end(),sr.begin()+32,sr.begin()+96);results.insert(results.end(),cr.begin()+32,cr.begin()+96);results.insert(results.end(),actual,actual+10);auto appended=data;appended.resize(n+8);crc64_invert(actual[9],appended.data()+n);results.push_back(crc64(appended.data(),appended.size()));size_t split=12345;results.push_back(crc64_combine(crc64(data.data(),split),crc64(data.data()+split,n-split),n-split));guards.insert(guards.end(),sr.begin(),sr.begin()+32);guards.insert(guards.end(),sr.begin()+96,sr.end());guards.insert(guards.end(),cr.begin(),cr.begin()+32);guards.insert(guards.end(),cr.begin()+96,cr.end());CHECK(cudaFree(d));CHECK(cudaFree(t));CHECK(cudaFree(it));CHECK(cudaFree(cb));CHECK(cudaFree(sb));}
const unsigned char known[]="123456789";results.push_back(crc64_parallel(known,9));prefix.insert(prefix.end(),crc64_x_pow_2n,crc64_x_pow_2n+64);prefix.insert(prefix.end(),known,known+9);prefix.insert(prefix.end(),{65555,65677,64,10,9});bool ok=results==oracle;for(auto g:guards)ok&=g==sentinel;all&=ok;std::vector<uint64_t>artifact=prefix;artifact.insert(artifact.end(),results.begin(),results.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":537,\"max_abs_error\":%s,\"max_rel_error\":null,\"timing_region\":\"sum_two_original_parallelCRC_API_allocation_copy_kernel_readback_CPUcombine_free_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"timed_cases\":2,\"component_time_seconds\":{\"bytes65555\":%.12g,\"bytes65677\":%.12g},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",ok?"0":"null",times[0],times[1],path.c_str(),artifact.size());}return all?0:1;}
